Hi @reporter,
could you please try `OPENSSL_armcap=0x2afd make test`
and `OPENSSL_armcap=0x6afd make test`
with this patch applied?
```
--- a/crypto/chacha/asm/chacha-armv8-sve.pl
+++ b/crypto/chacha/asm/chacha-armv8-sve.pl
@@ -248,9 +248,6 @@ sub load_regs() {
        my $next_offset = $offset + 1;
 $code.=<<___;
        ld1w    {$reg.s},p0/z,[$inp,#$offset,MUL VL]
-#ifdef  __AARCH64EB__
-       revb    $reg.s,p0/m,$reg.s
-#endif
 ___
        if (@_) {
                &load_regs($next_offset, @_);
@@ -272,9 +269,6 @@ sub store_regs() {
        my $reg = shift;
        my $next_offset = $offset + 1;
 $code.=<<___;
-#ifdef  __AARCH64EB__
-       revb    $reg.s,p0/m,$reg.s
-#endif
        st1w    {$reg.s},p0,[$outp,#$offset,MUL VL]
 ___
        if (@_) {
@@ -875,8 +869,7 @@ my  %opcode_pred = (
        "ld1w"         => 0xA540A000,
        "ld1rw"        => 0x8540C000,
        "lasta"        => 0x0520A000,
-       "revh"         => 0x05258000,
-       "revb"         => 0x05248000);
+       "revh"         => 0x05258000);

 my  %tsize = (
        'b'          => 0,
